import{_ as s,o as a,c as t,ag as o}from"./chunks/framework.DXGyWiRo.js";const m=JSON.parse('{"title":"Custom Framework","description":"","frontmatter":{},"headers":[],"relativePath":"framework/custom.md","filePath":"framework/custom.md","lastUpdated":1785990345000}'),i={name:"framework/custom.md"};function r(n,e,d,l,p,h){return a(),t("div",null,[...e[0]||(e[0]=[o(`<h1 id="custom-framework" tabindex="-1">Custom Framework <a class="header-anchor" href="#custom-framework" aria-label="Permalink to &quot;Custom Framework&quot;">​</a></h1><p>The <strong>Custom</strong> framework lets you describe an API convention with configuration rules when a project does not use one of EasyYapi&#39;s built-in framework recognizers.</p><p>Unlike Spring, JAX-RS, Feign, and gRPC support, Custom has no hard-coded annotation detection. Class recognition, method recognition, HTTP method, path, and parameter binding are all controlled by <code>custom.*</code> rules. Once a rule produces a normal API endpoint, every enabled export channel—including YApi—can consume it.</p><h2 id="enable-custom" tabindex="-1">Enable Custom <a class="header-anchor" href="#enable-custom" aria-label="Permalink to &quot;Enable Custom&quot;">​</a></h2><p>Custom is disabled by default. Open <strong>Settings</strong> &gt; <strong>Other Settings</strong> &gt; <strong>EasyApi</strong> &gt; <strong>Features</strong>, enable <strong>custom</strong> under <strong>Framework Support</strong>, and then add rules to a project or global <code>.easyapi/*.rules</code> file.</p><p>Custom line markers are also opt-in. If you want gutter icons for classes recognized by Custom rules, open the Custom framework settings and enable <strong>line marker for Custom API classes</strong>.</p><h2 id="core-rules" tabindex="-1">Core rules <a class="header-anchor" href="#core-rules" aria-label="Permalink to &quot;Core rules&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Rule</th><th>Purpose</th></tr></thead><tbody><tr><td><code>custom.class.is.api</code></td><td>Identifies an API class</td></tr><tr><td><code>custom.method.is.api</code></td><td>Identifies an endpoint method</td></tr><tr><td><code>custom.http.method</code></td><td>Supplies the HTTP verb</td></tr><tr><td><code>custom.path</code></td><td>Supplies the class or method path</td></tr><tr><td><code>custom.param.as.json.body</code></td><td>Binds a parameter as a JSON body</td></tr><tr><td><code>custom.param.as.form.body</code></td><td>Binds a parameter as a form field</td></tr><tr><td><code>custom.param.as.path.var</code></td><td>Binds a parameter as a path variable</td></tr><tr><td><code>custom.param.as.cookie</code></td><td>Binds a parameter as a cookie</td></tr><tr><td><code>custom.param.name</code></td><td>Overrides a query or form parameter name</td></tr><tr><td><code>custom.param.header</code> / <code>custom.param.cookie</code></td><td>Supplies header or cookie names</td></tr></tbody></table><p>For less specific parameter rules, <code>param.http.type</code> can classify a parameter as <code>query</code>, <code>path</code>, <code>header</code>, <code>cookie</code>, <code>form</code>, or <code>body</code>. The specific <code>custom.param.as.*</code> classifiers take precedence.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><p>The following is a starting point for a project whose API classes and methods use custom annotations. Replace the annotation names and paths with the conventions used by your project:</p><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">custom.class.is.api</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=groovy:it.hasAnn(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;com.example.ApiController&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">custom.method.is.api</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=groovy:it.hasAnn(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;com.example.Api&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">custom.http.method</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=groovy:it.ann(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;com.example.Api&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)?.value() ?: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;GET&quot;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">custom.path</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=groovy:it.ann(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;com.example.Path&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)?.value() ?: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">custom.param.as.json.body</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=groovy:it.hasAnn(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;com.example.JsonBody&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">custom.param.as.path.var</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=groovy:it.hasAnn(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;com.example.PathVariable&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>The HTTP method falls back to <code>method.default.http.method</code>, then to <code>POST</code> if no rule supplies a value. The final path combines the class path, method path, <code>class.prefix.path</code>, and <code>endpoint.prefix.path</code> with duplicate slashes normalized.</p><h2 id="lifecycle-hooks" tabindex="-1">Lifecycle hooks <a class="header-anchor" href="#lifecycle-hooks" aria-label="Permalink to &quot;Lifecycle hooks&quot;">​</a></h2><p>Custom also provides framework-scoped hooks for rules that should run only during Custom extraction:</p><ul><li><code>custom.class.parse.before</code> / <code>custom.class.parse.after</code></li><li><code>custom.method.parse.before</code> / <code>custom.method.parse.after</code></li><li><code>custom.export.after</code></li></ul><p>The shared API parse and export hooks remain available as well.</p><h2 id="migrating-from-generic-export-rules" tabindex="-1">Migrating from generic export rules <a class="header-anchor" href="#migrating-from-generic-export-rules" aria-label="Permalink to &quot;Migrating from generic export rules&quot;">​</a></h2><p>The old v2 <code>mdoc.class.filter</code> and <code>mdoc.method.filter</code> keys are not supported by the v3 rewrite. Use the Custom recognizer instead:</p><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">custom.class.is.api</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=groovy:it.hasAnn(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;com.example.ApiController&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">custom.method.is.api</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=groovy:it.hasAnn(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;com.example.Api&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>See <a href="/settings/config-rule">Config Rules</a> and <a href="/settings/rule-authoring">Rule Authoring</a> for the rule file format and AI-assisted authoring workflow.</p>`,21)])])}const u=s(i,[["render",r]]);export{m as __pageData,u as default};
